<?php $research=Serp::saved($wid,'keyword_research');?>
<div class="ranking-hero"><div><span class="eyebrow">KEYWORD RESEARCH</span><h2>Find searches worth creating content for.</h2><p>Explore Google results, related searches and questions, then add relevant ideas to your tracked keywords.</p></div><a class="button secondary" href="<?=url('/keywords?website_id='.$wid)?>">Tracked keyword analysis</a></div>
<section class="card stack"><form data-api="research"><input type="hidden" name="website_id" value="<?=$wid?>"><label>Seed keyword<input name="seed" required maxlength="190" value="<?=e($research['seed']??'')?>" placeholder="For example: digital marketing agency in Delhi"></label><p class="small"><?=e($w['country'].' · '.$w['language'])?> · Searches use your project audience. Repeated searches for the same seed reuse today's saved result.</p><button class="button">Analyze keyword</button></form></section>
<?php if($research):?><section class="card stack"><div class="card-header"><div><h3>Ideas for “<?=e($research['seed'])?>”</h3><p class="small"><?=e($research['source'].' · '.$research['checked_at'].' UTC')?></p></div><span class="badge"><?=count($research['ideas'])?> ideas</span></div><?php if($research['corrected']??''):?><p class="alert">Google showed results for: <?=e($research['corrected'])?></p><?php endif;?>
<div class="table-wrap"><table><thead><tr><th>Keyword / question</th><th>Origin</th><th>Monthly volume</th><th>Difficulty</th><th>Action</th></tr></thead><tbody><?php foreach($research['ideas'] as $i=>$idea):?><tr><td><?=e($idea['keyword'])?></td><td><?=e($idea['type'])?></td><td><?=e($idea['search_volume']??'Not supplied')?></td><td><?=e($idea['difficulty']??'Not supplied')?></td><td><button class="button secondary small-button" data-action="research-add" data-website-id="<?=$wid?>" data-index="<?=$i?>">Track keyword</button></td></tr><?php endforeach;?></tbody></table></div><p class="small">HasData SERP supplies search results and suggestions, not search-volume or difficulty estimates. A keyword data gateway or CSV import can supply those metrics.</p></section>
<section class="card stack"><h3>Pages currently appearing on Google</h3><?php foreach($research['organic'] as $r):?><article class="issue"><span class="badge">#<?=e($r['position'])?></span> <a href="<?=e($r['url'])?>" target="_blank" rel="noopener noreferrer"><?=e($r['title'])?></a><p><?=e($r['snippet'])?></p><span class="small"><?=e($r['url'])?></span></article><?php endforeach;if(!$research['organic'])empty_state('No result pages supplied','Your configured keyword provider returned keyword suggestions only.');?></section><?php endif;?>
